const buildPrompt = $('Build Prompt').first().json;
const aiOutput = $('AI Agent').first().json.output || '';
const systemPrompt = buildPrompt.systemPrompt || '';
const userMessage = buildPrompt.userMessage || '';

const totalChars = systemPrompt.length + userMessage.length + aiOutput.length;
const tokensUsed = Math.max(1, Math.ceil(totalChars / 4));

return {
  json: {
    agentId: buildPrompt.agentId,
    userId: buildPrompt.userId,
    clientId: $('Get Agent Data').first().json.client_id,
    tokensUsed,
    output: aiOutput
  }
};

// Acceso a datos por nodo
const agentData = $('Get Agent Data').first().json;
const webhookData = $('Normalize Webhook Data').first().json;
const chatHistoryData = $input.all().find(i => i.json.chat_history)?.json;
const chatHistory = chatHistoryData?.chat_history || [];

const userMessage = webhookData.userMessage;
const userId = webhookData.userId;
const agentId = agentData.agent_id;
const agent = agentData;

// Construir historial
let conversationContext = '';
if (chatHistory.length > 0) {
  conversationContext = `
🧠 ESTA ES LA CONVERSACIÓN QUE YA TUVISTE CON ESTE CLIENTE:

${chatHistory.map((item, index) => {
  const role = item.role === 'user' ? '👤 Cliente' : '🤖 Tú dijiste';
  return `[Mensaje ${index + 1}] ${role}: "${item.message}"`;
}).join('\n')}

⚠️ INSTRUCCIONES CRÍTICAS:
1. Lee TODOS los mensajes anteriores antes de responder
2. Si el cliente ya te dio información, NO la vuelvas a preguntar
3. Usa la información de mensajes anteriores para dar contexto

`;
} else {
  conversationContext = '\n🆕 ESTA ES LA PRIMERA INTERACCIÓN CON ESTE CLIENTE\n\n';
}

// Formatear info del agente
const priceRange = agent.price_range;
const products = agent.products;
const paymentMethods = agent.payment_methods;
const faqs = agent.faqs;
const personality = agent.agent_personality;

let formattedProducts = '';
if (products && products.length > 0) {
  formattedProducts = products.map(p => {
    let productInfo = `${p.name}: $${p.price}`;
    if (p.description) productInfo += `\n  ${p.description}`;
    if (p.image_url) productInfo += `\n  🖼️ Ver imagen: ${p.image_url}`;
    return productInfo;
  }).join('\n\n');
}

let formattedPayments = paymentMethods?.length ? paymentMethods.join('; ') : '';
let formattedFaqs = faqs?.length ? faqs.map(f => `P: ${f.question}\nR: ${f.answer}`).join('\n\n') : '';
let formattedTone = personality?.tone || 'amigable';
let formattedFormality = personality?.formality || 'tutear';
let formattedEmojis = personality?.useEmojis ? 'Sí, usa emojis' : 'No uses emojis';
let formattedCustomInstructions = agent.custom_instructions?.trim() || '';

const systemPrompt = `Eres un agente de ventas por WhatsApp para ${agent.business_name}.

${conversationContext}

=== INFORMACIÓN DEL NEGOCIO ===
Tipo: ${agent.business_type}
Categoría: ${agent.business_category}
Rango de precios: $${priceRange?.from || 0} - $${priceRange?.to || 0} ${priceRange?.currency || 'USD'}

=== PRODUCTOS/SERVICIOS ===
${formattedProducts}

=== FORMAS DE PAGO ===
${formattedPayments}

=== PREGUNTAS FRECUENTES ===
${formattedFaqs}

=== TU PERSONALIDAD ===
- Tono: ${formattedTone}
- Formalidad: ${formattedFormality}
- Emojis: ${formattedEmojis}

=== INSTRUCCIONES PRIORITARIAS ===
${formattedCustomInstructions}

=== REGLAS FINALES ===
1. SIEMPRE lee el historial antes de responder
2. NO repitas preguntas
3. Máximo 3 líneas por mensaje
4. Una pregunta a la vez

Responde en español de forma natural como en WhatsApp.`;

return {
  systemPrompt,
  userMessage,
  userId,
  agentId,
  sessionId: `${agentId}_${userId}`
};

